const PlasmicDescendants = {
  root: [
    "root",
    "navbar",
    "heroSection",
    "h1",
    "optimizedImage",
    "problemAndSolution",
    "problemSolutionLayout",
    "formSection",
    "footerSection"
  ],
  navbar: ["navbar"],
  heroSection: ["heroSection", "h1", "optimizedImage"],
  h1: ["h1"],
  optimizedImage: ["optimizedImage"],
  problemAndSolution: ["problemAndSolution", "problemSolutionLayout"],
  problemSolutionLayout: ["problemSolutionLayout"],
  formSection: ["formSection"],
  footerSection: ["footerSection"]
} as const;
type NodeNameType = keyof typeof PlasmicDescendants;
type DescendantsType<T extends NodeNameType> =
  (typeof PlasmicDescendants)[T][number];
type NodeDefaultElementType = {
  root: "div";
  navbar: typeof Navbar;
  heroSection: "section";
  h1: "h1";
  optimizedImage: typeof OptimizedImage;
  problemAndSolution: "section";
  problemSolutionLayout: "div";
  formSection: typeof FormSection;
  footerSection: typeof FooterSection;
};

type ReservedPropsType = "variants" | "args" | "overrides";
type NodeOverridesType<T extends NodeNameType> = Pick<
  PlasmicCases__OverridesType,
  DescendantsType<T>
>;
type NodeComponentProps<T extends NodeNameType> =
  // Explicitly specify variants, args, and overrides as objects
  {
    variants?: PlasmicCases__VariantsArgs;
    args?: PlasmicCases__ArgsType;
    overrides?: NodeOverridesType<T>;
  } &
    // Specify variants directly as props
    Omit<PlasmicCases__VariantsArgs, ReservedPropsType> &
    // Specify args directly as props
    Omit<PlasmicCases__ArgsType, ReservedPropsType> &
    // Specify overrides for each element directly as props
    Omit<
      NodeOverridesType<T>,
      ReservedPropsType | VariantPropType | ArgPropType
    > &
    // Specify props for the root element
    Omit<
      Partial<React.ComponentProps<NodeDefaultElementType[T]>>,
      ReservedPropsType | VariantPropType | ArgPropType | DescendantsType<T>
    >;

function makeNodeComponent<NodeName extends NodeNameType>(nodeName: NodeName) {
  type PropsType = NodeComponentProps<NodeName> & { key?: React.Key };
  const func = function <T extends PropsType>(
    props: T & StrictProps<T, PropsType>
  ) {
    const { variants, args, overrides } = React.useMemo(
      () =>
        deriveRenderOpts(props, {
          name: nodeName,
          descendantNames: PlasmicDescendants[nodeName],
          internalArgPropNames: PlasmicCases__ArgProps,
          internalVariantPropNames: PlasmicCases__VariantProps
        }),
      [props, nodeName]
    );
    return PlasmicCases__RenderFunc({
      variants,
      args,
      overrides,
      forNode: nodeName
    });
  };
  if (nodeName === "root") {
    func.displayName = "PlasmicCases";
  } else {
    func.displayName = `PlasmicCases.${nodeName}`;
  }
  return func;
}

export const PlasmicCases = Object.assign(
  // Top-level PlasmicCases renders the root element
  makeNodeComponent("root"),
  {
    // Helper components rendering sub-elements
    navbar: makeNodeComponent("navbar"),
    heroSection: makeNodeComponent("heroSection"),
    h1: makeNodeComponent("h1"),
    optimizedImage: makeNodeComponent("optimizedImage"),
    problemAndSolution: makeNodeComponent("problemAndSolution"),
    problemSolutionLayout: makeNodeComponent("problemSolutionLayout"),
    formSection: makeNodeComponent("formSection"),
    footerSection: makeNodeComponent("footerSection"),

    // Metadata about props expected for PlasmicCases
    internalVariantProps: PlasmicCases__VariantProps,
    internalArgProps: PlasmicCases__ArgProps,

    pageMetadata: generateDynamicMetadata(wrapQueriesWithLoadingProxy({}), {
      pageRoute: "/[locale]/cases/[slug]",
      pagePath: "/[locale]/cases/[slug]",
      params: {},
      query: {}
    })
  }
);

export default PlasmicCases;
